def refs():
    return [{**s, "subject": "science", "observedPattern": "公立學校公開自然／理化試題常用氣密注射器、活塞、壓力表與資料表考查定溫定量下的壓力—體積反比、pV 計算及控制條件；本題只取能力方向並重新設計情境、數據與選項。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-ec-iv-2-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然／理化資料僅作定溫定量氣體的壓力、體積、注射器與資料判讀能力方向研究；未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與公立學校公開試題能力方向獨立改寫，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-12", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "在溫度與氣體量固定、沒有漏氣時，氣體體積縮小為原來一半，壓力通常如何變化？", {"A": "變為原來一半", "B": "變為原來兩倍", "C": "保持不變", "D": "變為原來四倍"}, "B", "定溫定量時 pV 為常數；體積變為 1/2，壓力須變為 2 倍，才能保持乘積不變。", "先確認波以耳定律適用條件，再用體積倍數反向判斷壓力倍數。", ["確認溫度固定。", "確認氣體量固定且沒有漏氣。", "體積變為原來的 1/2。", "pV 固定，所以壓力要變為 2 倍。", "因此選壓力變為原來兩倍。"], "easy"),
    make(2, "某氣體在定溫定量下，p＝60 kPa、V＝20 mL。若體積改為 10 mL，壓力為何？", {"A": "30 kPa", "B": "60 kPa", "C": "120 kPa", "D": "200 kPa"}, "C", "p₁V₁＝p₂V₂，所以 p₂＝(60×20)/10＝120 kPa。體積減半，壓力加倍。", "先寫 p₁V₁＝p₂V₂，再整理未知量並檢查反比方向。", ["列出 p₁＝60 kPa、V₁＝20 mL。", "列出 V₂＝10 mL。", "寫出 60×20＝p₂×10。", "計算 p₂＝120 kPa。", "體積減半而壓力加倍，答案為 120 kPa。"], "medium"),
    make(3, "氣密注射器中同一份空氣在定溫下測得 V＝20、16、10 mL 時，壓力分別為 60、75、120 kPa。哪一項最能支持模型？", {"A": "每次壓力都增加 15 kPa", "B": "pV 乘積皆約為 1200 kPa·mL", "C": "體積越小，pV 越小", "D": "只看活塞位置即可，不必看單位"}, "B", "60×20＝1200、75×16＝1200、120×10＝1200，乘積近似固定，支持定溫定量的 pV 常數模型。", "把每組壓力與體積相乘，比較乘積是否近似相同。", ["逐組讀取 p 與 V。", "計算 60×20＝1200。", "計算 75×16＝1200 與 120×10＝1200。", "比較三組乘積，發現近似固定。", "因此資料支持 pV 為常數。"], "medium"),
    make(4, "下列哪一項是直接套用 p₁V₁＝p₂V₂ 前必須確認的條件？", {"A": "氣體溫度與氣體量固定", "B": "容器一定是透明的", "C": "活塞一定向右移動", "D": "氣體顏色保持不變"}, "A", "波以耳定律適用於溫度與氣體量固定的同一份氣體；容器顏色、透明度與活塞方向不是定律的必要條件。", "先檢查定律的控制變因，不被裝置外觀或移動方向取代。", ["辨認要使用的是定溫定量的壓力體積關係。", "溫度改變會影響粒子運動狀態。", "氣體量改變會改變粒子數。", "所以兩者都須固定或已知如何處理。", "因此選溫度與氣體量固定。"], "easy"),
    make(5, "把氣密注射器中的活塞推入較小體積時，若溫度近似不變，壓力升高的粒子模型解釋是？", {"A": "粒子本身變大", "B": "粒子數量自動增加", "C": "粒子活動空間變小，單位時間撞擊器壁的機會增加", "D": "重力方向轉向器壁"}, "C", "壓縮時粒子本身不會被壓扁，沒有漏氣時粒子數也不增加；可活動空間變小，使撞擊器壁更頻繁，壓力升高。", "先排除粒子大小與數量改變，再用碰撞頻率解釋壓力變化。", ["確認沒有漏氣，所以粒子數固定。", "確認溫度近似固定，粒子平均運動狀態近似不變。", "活塞推入使可活動體積變小。", "粒子更常撞擊器壁。", "因此平均壓力升高。"], "medium"),
    make(6, "若定溫定量氣體的體積由 30 mL 變成 45 mL，原壓力為 90 kPa，新的壓力約為？", {"A": "60 kPa", "B": "90 kPa", "C": "135 kPa", "D": "270 kPa"}, "A", "p₂＝p₁V₁/V₂＝90×30/45＝60 kPa。體積增加 1.5 倍，壓力變為原來 2/3。", "先保持 pV 乘積，再做比例計算並檢查體積增加時壓力應下降。", ["列出 p₁＝90 kPa、V₁＝30 mL。", "列出 V₂＝45 mL。", "寫 p₂＝90×30÷45。", "計算得到 p₂＝60 kPa。", "體積增加而壓力下降，與反比方向一致。"], "medium"),
    make(7, "下列哪一種情況不適合直接使用原本的 pV＝常數關係？", {"A": "同一氣密注射器、溫度固定、活塞慢慢移動", "B": "同一份氣體、溫度固定、體積改變", "C": "壓縮時容器漏氣，且氣體量不再固定", "D": "同一氣體在不同體積讀取壓力"}, "C", "pV＝常數要求同一份氣體且溫度與氣體量固定；漏氣會改變氣體量，因此不能直接套用原本的常數。", "逐項檢查定溫、定量與密閉條件，找出違反條件者。", ["列出波以耳定律的主要條件。", "檢查每個情境是否同一份氣體。", "漏氣會使氣體粒子數改變。", "氣體量不固定時 pV 不必維持原值。", "所以漏氣的壓縮情況不能直接套用。"], "hard"),
    make(8, "若把壓力 p 對 1/V 作圖，定溫定量的理想資料較接近哪種圖形？", {"A": "水平直線", "B": "通過原點的直線", "C": "向下彎曲的反比曲線", "D": "垂直直線"}, "B", "pV＝常數可改寫為 p＝常數×(1/V)，因此 p 對 1/V 應較接近通過原點的直線；p 對 V 才呈反比曲線。", "先把公式改寫成縱軸對橫軸的形式，再判斷圖形。", ["從 pV＝常數開始。", "整理為 p＝常數×1/V。", "把 1/V 當作橫軸。", "這是正比關係，理想情況為通過原點的直線。", "所以選直線圖形。"], "hard"),
    make(9, "同一份氣體在定溫下由 100 kPa、12 mL 變成 80 kPa 時，體積應為多少？", {"A": "9.6 mL", "B": "12 mL", "C": "15 mL", "D": "20 mL"}, "C", "p₂V₂＝p₁V₁，所以 V₂＝100×12/80＝15 mL。壓力降低至 0.8 倍，體積增加為 1.25 倍。", "用 p₁V₁＝p₂V₂ 解未知體積，再用反比關係做合理性檢查。", ["列出 p₁＝100 kPa、V₁＝12 mL。", "列出 p₂＝80 kPa。", "寫 V₂＝100×12÷80。", "計算 V₂＝15 mL。", "壓力降低，體積增加，方向合理。"], "medium"),
    make(10, "壓縮氣體後立即讀取壓力，若活塞摩擦或溫度尚未恢復，資料偏離理想 pV 常數時應如何判斷？", {"A": "直接宣布定律錯誤", "B": "先檢查溫度、摩擦、漏氣與讀值時機等測量條件", "C": "把所有偏差都改成零", "D": "只看最後一次讀值即可"}, "B", "理想關係需定溫定量且量測穩定；活塞摩擦、溫度變化、漏氣或未等候平衡都可能造成偏差，應先檢查實驗條件。", "遇到資料不吻合時先查控制條件與測量誤差，不立即否定模型。", ["確認理想模型假設定溫、定量與穩定讀值。", "列出可能的偏差來源。", "檢查摩擦、溫度、漏氣與等待時間。", "比較修正條件後的資料是否更接近 pV 常數。", "所以應先檢查實驗品質再下結論。"], "hard"),
]

